export async function fetchMitTimeout(url, ms) {
  const timeout = new Promise((_, reject) => {
    setTimeout(() => reject(new Error(`Abbruch nach ${ms} ms`)), ms);
  });

  try {
    const fetchPromise = fetch(url);
    const result = await Promise.race([fetchPromise, timeout]);
    return result;
  } catch (error) {
    if (error.message.includes('Abbruch')) {
      throw error;
    }
    throw error;
  }
}
```

Die Funktion startet einen fetch und wartet gleichzeitig auf einen Timeout. Wenn der Timeout kommt, wird der Fehler ausgeliefert. Wenn der fetch erfolgreich ist, wird er zurückgegeben. Die Abbruch-Logik ist fail-closed: nur der Timeout wird abgebrochen, kein anderer Fehler wird ignoriert.

